// Thresholds map a metric id to a minimum score, e.g. { exact_match: 0.9 }.
const toThresholdEntries = (thresholds) => {
  if (!thresholds) return [];
  return Object.entries(thresholds).map(([metric, min]) => {
    if (typeof min !== 'number' || !Number.isFinite(min) || min < 0 || min > 1) {
      throw new Error(`Threshold for "${metric}" must be a number between 0 and 1.`);
    }
    return { metric, min };
  });
};

export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  thresholds,
  generatedAt = new Date().toISOString()
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  const thresholdEntries = toThresholdEntries(thresholds);
  if (thresholdEntries.length) {
    // A metric without a numeric score (or absent from the run) fails its threshold.
    const results = thresholdEntries.map(({ metric, min }) => {
      const evaluation = evaluations.find((item) => item.id === metric);
      const score = typeof evaluation?.score === 'number' ? evaluation.score : null;
      return { metric, min, score, passed: score !== null && score >= min };
    });
    report.passed = results.every((result) => result.passed);
    report.thresholds = results;
  }

  return report;
}

