// Usage errors exit 2 so CI can tell a bad command line apart from a failed threshold (exit 1).
function usageError(message: string): never {
  log.error(message);
  process.exit(2);
}

function parseEvalThresholds(specs: string[]): Record<string, number> {
  const validIds = Eval.DEFAULT_METRIC_IDS as unknown as string[];
  const thresholds: Record<string, number> = {};
  specs.forEach((spec) => {
    const match = /^([^=]+)=(\d+(?:\.\d*)?|\.\d+)$/.exec(spec);
    if (!match) {
      usageError(`Invalid --threshold "${spec}": expected <metric>=<min>, for example exact_match=0.9.`);
    }
    const [, metric, minText] = match;
    if (!validIds.includes(metric)) {
      usageError(`Unknown metric "${metric}" in --threshold. Valid metric ids: ${validIds.join(', ')}.`);
    }
    const min = Number(minText);
    if (min > 1) {
      usageError(`Invalid --threshold "${spec}": the minimum must be between 0 and 1.`);
    }
    if (metric in thresholds) {
      usageError(`Duplicate --threshold for metric "${metric}".`);
    }
    thresholds[metric] = min;
  });
  return thresholds;
}

function runEvalCommand(options: EvalOptions) {
  const thresholds = parseEvalThresholds(options.threshold ?? []);
  assertFileExists(options.outputs);
  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });
  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds
  });
  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  if (!report.thresholds) return;
  const failed = report.thresholds.filter((threshold: { passed: boolean }) => !threshold.passed);
  if (!failed.length) {
    log.success('All thresholds passed.');
    return;
  }
  failed.forEach((threshold: { metric: string; score: number | null; min: number }) => {
    log.error('Threshold not met.', {
      metric: threshold.metric,
      score: threshold.score ?? 'n/a',
      minimum: threshold.min
    });
  });
  process.exit(1);
}

